import assert from 'node:assert/strict';
import { createServer } from 'node:http';
import { mkdtemp, writeFile, readFile } from 'node:fs/promises';
import { join } from 'node:path';
import { createHash } from 'node:crypto';
import { rlmLoop } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/rlm.js';
import { parseCustomProviders } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/custom-providers.js';
import { LegacyMikroBackend } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/mcp/backends/legacy.js';
import { runTurn } from '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/mcp/server.js';
const verifyPreserved = process.argv.includes('--verify-preserved');
const proofRoot = await mkdtemp('/home/genie/.local/share/mikro-engine-split/experiments-g8/rlm-cap-receipt-proof-');
let requests = 0;
const server = createServer(async (req, res) => {
  for await (const _chunk of req) {}
  requests++;
  res.writeHead(200, { 'Content-Type': 'text/event-stream' });
  const text = verifyPreserved && requests === 2 ? '```repl\nprint(llm_query("bounded local subcall"))\n```' : verifyPreserved && requests === 3 ? 'subcall answer' : "```repl\nprint('not final')\n```";
  res.end(`data: ${JSON.stringify({ id: 'isolated-packet-fixture', object: 'chat.completion.chunk', model: 'control', choices: [{ index: 0, delta: { role: 'assistant', content: text }, finish_reason: 'stop' }], usage: { prompt_tokens: 11, completion_tokens: 7, total_tokens: 18 } })}\n\ndata: [DONE]\n\n`);
});
await new Promise(resolve => server.listen(0, '127.0.0.1', resolve));
const address = server.address();
assert(address && typeof address !== 'string');
const providers = parseCustomProviders({ 'receipt-fixture': { 'base-url': `http://127.0.0.1:${address.port}/v1`, 'api-key-env': 'MIKRO_RLM_RECEIPT_FIXTURE_KEY', models: { control: { cost: { input: 1, output: 2 } } } } }, 'isolated receipt diagnostic');
process.env.MIKRO_RLM_RECEIPT_FIXTURE_KEY = 'fixture-only-not-a-credential';
const config = { system: null, tools: [], criteria: null, model: { provider: 'receipt-fixture', model: 'control', providers }, configDir: proofRoot, budget: { maxCost: null, maxTokens: null, maxDepth: 0 }, contextConfig: { extensions: ['.md'], exclude: ['node_modules'] }, toolsLevel: 'core', cache: { enabled: false, strategy: 'full', retention: 'long' }, gemini: { thinkingLevel: null, googleSearch: false, urlContext: false, codeExecution: false, computerUse: false, mapsGrounding: false, fileSearch: false, mediaResolution: null }, output: { schema: null }, storage: { enabled: 'never', mode: 'persistent', dataDir: join(proofRoot, 'data'), port: 0, chunkSize: null, chunkUtilization: 0.6, charsPerToken: 4 }, prompt: { appendStopProtocol: true }, validate: null, providers, configSource: 'yaml' };
let failure;
let outcome;
let zeroCallOutcome;
try {
  try { await rlmLoop('isolated no-external-inference receipt diagnostic', null, config, { maxIterations: 1, maxRetries: 0, output: 'json' }); }
  catch (error) { failure = { name: error.name, message: error.message, receipt: error.receipt ?? null, usage: error.usage ?? null, iterations: error.iterations ?? null, budgetHit: error.budgetHit ?? null, usageComplete: error.usageComplete ?? null }; }
  if (verifyPreserved) {
    config.budget.maxDepth = null;
    outcome = await runTurn(new LegacyMikroBackend(), undefined, config, 'receipt-fixture', 'bounded root and IPC receipt smoke', 'isolated-session', undefined, proofRoot, undefined, 1);
    config.budget.maxTokens = 0;
    zeroCallOutcome = await runTurn(new LegacyMikroBackend(), undefined, config, 'receipt-fixture', 'zero-call budget smoke', 'isolated-zero-session', undefined, proofRoot, undefined, 1);
  }
} finally { delete process.env.MIKRO_RLM_RECEIPT_FIXTURE_KEY; server.closeAllConnections(); await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve())); }
assert.equal(requests, verifyPreserved ? 3 : 1);
assert(failure && /maxIterations exhausted/.test(failure.message));
const reproduced = failure.receipt === null && failure.usage === null;
let observed;
if (verifyPreserved) {
  assert.equal(failure.iterations, 1);
  assert.equal(failure.usage.inputTokens, 11);
  assert.equal(failure.usage.outputTokens, 7);
  assert.equal(failure.usage.llmCalls, 1);
  assert.equal(failure.usageComplete, false);
  assert(outcome.failed && /failed: RLM maxIterations exhausted/.test(outcome.answer));
  const line = outcome.text.split('\n').find(text => text.startsWith('observed_usage: '));
  assert(line);
  observed = JSON.parse(line.slice('observed_usage: '.length));
  assert.equal(observed.coverage, 'partial');
  assert.equal(observed.iterations, 1);
  assert.equal(observed.totals, null);
  assert.equal(observed.subtotal.inputTokens, 22);
  assert.equal(observed.subtotal.outputTokens, 14);
  assert(Math.abs(observed.subtotal.totalCost - 0.00005) < 1e-12);
  assert(zeroCallOutcome.failed && zeroCallOutcome.text === zeroCallOutcome.answer);
}
const compiledPath = '/home/genie/orca/workspaces/genie/mikro-engine-split/mikro/dist/src/rlm.js';
const proof = { schemaVersion: 1, kind: verifyPreserved ? 'actual-compiled-RLM-and-MCP-failure-receipt-after-smoke' : 'actual-compiled-RLM-local-packet-accounting-loss-diagnosis', externalModelCalls: 0, realPython: true, realCompiledLoop: true, sourceOrArtifactModified: false, requests, observedPacketUsage: { inputTokens: 11, outputTokens: 7, totalTokens: 18, fixtureCatalogCostUsd: 0.000025, costKind: 'local-fixture-not-paid-inference' }, failure, reproduced, knownSubtotalPreserved: verifyPreserved && !reproduced, actualLegacyMcpFailure: outcome, actualZeroCallFailure: zeroCallOutcome, observedFailureFooter: observed, compiled: { path: compiledPath, sha256: createHash('sha256').update(await readFile(compiledPath)).digest('hex') }, proofRoot };
await writeFile(join(proofRoot, 'proof.json'), JSON.stringify(proof, null, 2) + '\n', { mode: 0o600, flag: 'wx' });
console.log(JSON.stringify({ proofPath: join(proofRoot, 'proof.json'), reproduced, knownSubtotalPreserved: verifyPreserved && !reproduced, requests, externalModelCalls: 0, failure, observedFailureFooter: observed }));
process.exitCode = (verifyPreserved ? !reproduced : reproduced) ? 0 : 2;
